function showMegaSearchModal() {
    $('#mega-search-modal').modal().show();
    $('#mega-search-modal').find('input').on('touchstart', function () {
        $('#mega-search-modal').find('input').focus();
    });
    $('#mega-search-modal').find('input').trigger('touchstart');
}

var topLevel = document.body;
$(topLevel).on("newQuery", function (e, args) {
    var bootstrap_enabled = (typeof $().emulateTransitionEnd == 'function');
     if (bootstrap_enabled === true) {
        $('#mega-search-modal').modal('hide');
    }
})

body.script:
$(".secondary-nav-inner-wrapper").each(function () {
    var targetDiv = $(this).find('.tab-content');
    $(this).find('.tab-pane').prependTo(targetDiv);
});

window.UPMCHeader = window.UPMCHeader || {};
window.UPMCHeader.updatePlaceholderHeight = function () {
    var $headerContainer = $(".header-megamenu").first();
    if (!$headerContainer.length) {
        return;
    }

    var updatedPlaceholderHeight = $headerContainer.height();
    $(".header-placeholder").css("height", updatedPlaceholderHeight + "px");
    $(".mobile-header .mega-menu-wrapper .mobile-main-nav-container, .mobile-search-drawer").css("top", updatedPlaceholderHeight + "px");
};

$(document).on('click', '.mobile-ad-close-btn', function () {
    var $adHeader = $(this).closest('.mobile-ad-header');
    var $headerContainer = $adHeader.closest('.header-megamenu');
    $adHeader.attr('aria-hidden', 'true').css('display', 'none');
    // move focus so it isn't lost when the ad is hidden
    $headerContainer.attr('tabindex', '-1').trigger('focus');

    // the ad is inside .header-megamenu, so its removal changes the header's
    // height; sync .header-placeholder and dependent positioned elements the
    // same way alert.js does when it closes an alert
    window.UPMCHeader.updatePlaceholderHeight();
});

var slideIndexMarketingAlert = 1;
showSlides(slideIndexMarketingAlert);

function plusSlides(n) {
    showSlides(slideIndexMarketingAlert += n);
}

function currentSlide(n) {
    showSlides(slideIndexMarketingAlert = n);
}

function showSlides(n) {
    var i;
    var slidesMarketingAlert = document.getElementsByClassName("marketingAlert");
    var marketingAlertContainer = document.getElementById("marketingAlertContainer");

    if (slidesMarketingAlert.length) { marketingAlertContainer.style.display = "flex"; }
    if (n > slidesMarketingAlert.length) { slideIndexMarketingAlert = 1 }
    if (n < 1) { slideIndexMarketingAlert = slidesMarketingAlert.length }
    for (i = 0; i < slidesMarketingAlert.length; i++) {
        slidesMarketingAlert[i].style.display = "none";
    }

    if (slidesMarketingAlert.length) { slidesMarketingAlert[slideIndexMarketingAlert - 1].style.display = "flex"; }
}

