                    $('body').append('<\/script>');
                }
            }
        });



     var store;

     $(document).ready(function () {

         //this is used to intersect specific "Suggested:" hero card and apply a custom class name
         const DETAILS_OPEN_ATTR_REGEX = /\sopen(?:=(?:"[^"]*"|'[^']*'|[^\s>]+))?/gi;

         const activityMiddleware = () => next => card => {
             const updatedCard = {
                 ...card,
                 text: card.text?.replace(
                     DETAILS_OPEN_ATTR_REGEX,
                     ''
                 ),
                 activity: card.activity
                     ? {
                         ...card.activity,
                         text: card.activity.text?.replace(
                             DETAILS_OPEN_ATTR_REGEX,
                             ''
                         )
                     }
                     : card.activity
             };

             return next(updatedCard);
         }

         const cardActionMiddleware = (conversationId) => () => next => action => {
             // Perform custom logic based on the card action type
             const cardActionType = action?.cardAction?.type;
             const cardActionTitle = (action?.cardAction?.title || '').trim();

             if (cardActionType === 'openUrl' && (cardActionTitle === 'View Profile & Schedule' || cardActionTitle === 'View Details')) {
                 let url = action.cardAction.value;
                 let words = url.split("/");
                 let providerName = words[4];
                 let providerId = words[5];
                 let formattedName = providerName.replace(/-/g, " ");
                 //trigger Piwik tracking
                 window.dataLayer.push({ 'event': 'upmc-aichat-providerClick', 'upmc-aichat-providerID': providerId, 'upmc-aichat-providerName': formattedName, 'upmc-aichat-chatID': conversationId });
                 url += "?upmcsrc=hb";
                 window.open(url, '_blank');
                 return;
             }
             else if (cardActionType === 'openUrl' && (cardActionTitle === 'UPMC Providers Site' || cardActionTitle === 'View All Providers')) {
                 let url = action.cardAction.value;
                 //trigger Piwik tracking
                 window.dataLayer.push({ 'event': 'upmc-aichat-viewAllClick', 'upmc-aichat-providerViewAllUrl': url, 'upmc-aichat-chatID': conversationId });
                 url += "&upmcsrc=hb";
                 window.open(url, '_blank');
                 return;
             }

             // Call the next middleware in the chain
             return next(action);
         }

         //Where available we change css using the API, if needed we revert to using css overrides
         const styleOptions = {
             primaryFont: "sans-serif",
             //Misc Styles
             hideUploadButton: true,
             hideTyping: false,
             backgroundColor: 'white',
             typingAnimationHeight: 20,
             typingAnimationWidth: 64,

             //Avatar Styles
             botAvatarInitials: "UPMC",
             botAvatarBackgroundColor: "#4D104A",
             userAvatarInitials: "YOU",
             userAvatarBackgroundColor: "#02809d",
             avatarSize: 46,

             //Suggested Actions Styles
             suggestedActionBackgroundColor: "white",
             suggestedActionBorderColor: "4D104A",
             suggestedActionTextColor: "#4D104A",
             suggestedActionBackgroundColorOnFocus: "#5762A7",
             suggestedActionBorderColorOnFocus: "#5762A7",
             suggestedActionTextColorOnFocus: "white",
             suggestedActionBackgroundColorOnHover: "#25646A",
             suggestedActionBorderColorOnHover: "#4D104A",
             suggestedActionTextColorOnHover: "White",
             suggestedActionBoarderWidth: 2,
             suggestedActionBorderRadius: 30,
             suggestedActionLayout: 'flow',
             paddingWide: 20, //used for suggestedActions Padding

             //Bot Styles
             bubbleBackground: "#ededed",
             bubbleBorderRadius: 15,

             //User Styles
             bubbleFromUserBackground: "#02809d",
             bubbleFromUserTextColor: "#fff",
             bubbleFromUserBorderRadius: 15,
             bubbleFromUserAlign: 'left',

             //Timestamp Styles
             groupTimestamp: 3000,
             showAvatarInGroup: 'timestamp',
             timestampColor: "White",
         };
         let DIRECTLINE;
         let chatState = false;
         let CONVERSATION_ID;
         let USERNAME = "Web Chat User";

         // Carousel buffering variables
         let providerCardBuffer = [];
         let providerBufferTimer = null;
         let carouselStore = null; // Reference to store for flushing carousel
         let referencesObserver = null;

         function collapseReferenceDetails(root) {
             const scope = root || document;
             const detailsNodes = scope.querySelectorAll('details.webchat__link-definitions[open]');
             detailsNodes.forEach(function (node) {
                 node.removeAttribute('open');
             });
         }

         function initReferenceDetailsObserver() {
             const webchatRoot = document.getElementById('webchat');
             if (!webchatRoot || referencesObserver) {
                 return;
             }

             collapseReferenceDetails(webchatRoot);

             referencesObserver = new MutationObserver(function (mutations) {
                 mutations.forEach(function (mutation) {
                     if (mutation.type === 'childList') {
                         mutation.addedNodes.forEach(function (node) {
                             if (node.nodeType !== 1) {
                                 return;
                             }
                             if (node.matches && node.matches('details.webchat__link-definitions[open]')) {
                                 node.removeAttribute('open');
                             }
                             collapseReferenceDetails(node);
                         });
                     }
                 });
             });

             referencesObserver.observe(webchatRoot, {
                 subtree: true,
                 childList: true
             });
         }

         // Flush buffered provider cards as carousel
         function flushProviderCarousel() {
             if (providerCardBuffer.length === 0) return;

             try {
                 // Create carousel activity with all required DirectLine fields
                 const carouselActivity = {
                     type: 'message',
                     id: 'carousel_' + Date.now(),
                     timestamp: new Date().toISOString(),
                     channelId: 'directline',
                     from: { 
                         role: 'bot',
                         id: 'bot',
                         name: 'Bot'
                     },
                     conversation: {
                         id: CONVERSATION_ID || 'default'
                     },
                     attachments: providerCardBuffer,
                     attachmentLayout: 'carousel',
                     channelData: {
                         isCarousel: true  // Flag to prevent re-processing
                     }
                 };

                 // Dispatch as new incoming activity
                 if (carouselStore) {
                     carouselStore.dispatch({
                         type: 'DIRECT_LINE/INCOMING_ACTIVITY',
                         payload: { activity: carouselActivity }
                     });

                     // Track carousel display
                     if (CONVERSATION_ID) {
                         window.dataLayer.push({ 
                             'event': 'upmc-aichat-carouselDisplayed', 
                             'upmc-aichat-carouselCount': providerCardBuffer.length,
                             'upmc-aichat-chatID': CONVERSATION_ID 
                         });
                     }
                 } else {
                     console.error('Carousel store not initialized');
                 }
             } catch (error) {
                 console.error('Error flushing carousel:', error);
             }

             // Clear buffer
             providerCardBuffer = [];
         }

         function createChatStore() {
             return window.WebChat.createStore({}, function (store) {
                 carouselStore = store; // Store reference for carousel flushing
                 return function (next) {
                     return function (action) {

                         // Auto-start: trigger a greeting/start topic when Direct Line connects
                         if (action.type === 'DIRECT_LINE/CONNECT_FULFILLED') {
                             store.dispatch({
                                 type: 'WEB_CHAT/SEND_EVENT',
                                 payload: {
                                     name: 'startConversation',
                                     value: { source: 'mvc' }
                                 }
                             });
                         }

                         if (action.type === 'DIRECT_LINE/INCOMING_ACTIVITY') {
                             if (action.payload.activity.text === "drScenario Start") {
                                 window.dataLayer.push({ 'event': 'upmc-aichat-providerScenario', 'upmc-aichat-chatID': action.payload.activity.conversation.id });
                                 return; // suppress — tracking signal, not user-visible
                             }
                             if (action.payload.activity.text === "masterScenario Start") {
                                 window.dataLayer.push({ 'event': 'upmc-aichat-conversationInitiated', 'upmc-aichat-chatID': action.payload.activity.conversation.id });
                                 return; // suppress — tracking signal, not user-visible
                             }
                         }
                         if (action.type === 'DIRECT_LINE/INCOMING_ACTIVITY') {
                             const activity = action.payload.activity;

                             if (activity?.text) {
                                 const sanitizedText = activity.text.replace(DETAILS_OPEN_ATTR_REGEX, '');
                                 if (sanitizedText !== activity.text) {
                                     action = Object.assign({}, action, {
                                         payload: {
                                             activity: Object.assign({}, activity, { text: sanitizedText })
                                         }
                                     });
                                 }
                             }

                             // Skip processing our own carousel activities
                             if (activity.channelData?.isCarousel === true) {
                                 return next(action);
                             }

                             // Keep typing activities intact so Web Chat can render the loading indicator.
                             if (activity && activity.type === 'typing') {
                                 return next(action);
                             }

                             // CAROUSEL LOGIC: Detect provider cards and buffer them
                             const isProviderCard = activity.attachments?.some(att => 
                                 att.content?.type === 'AdaptiveCard' && 
                                 att.content?.id === 'providerCard_id'
                             );

                             if (isProviderCard) {
                                 // Buffer this provider card
                                 providerCardBuffer.push(activity.attachments[0]);

                                 // Reset timer - wait for more cards
                                 clearTimeout(providerBufferTimer);
                                 providerBufferTimer = setTimeout(function() {
                                     flushProviderCarousel();
                                 }, 800); // 800ms timeout to collect all cards (increased from 500ms)

                                 // Suppress this individual card (don't render yet)
                                 return; // Don't call next(action)
                             }

                             // Detect end-of-sequence marker from bot
                             if (activity.channelData?.endProviders === true) {
                                 clearTimeout(providerBufferTimer);
                                 flushProviderCarousel();
                                 return; // Suppress the marker activity itself
                             }

                             // If we receive any other activity and have buffered cards, flush them first
                             if (providerCardBuffer.length > 0 && activity.from?.role === 'bot' && activity.type === 'message') {
                                 clearTimeout(providerBufferTimer);
                                 flushProviderCarousel();
                                 // Re-dispatch the current message on the next task so the carousel can render first.
                                 window.setTimeout(function () {
                                     next(action);
                                 }, 0);
                                 return;
                             }

                             // Only normalize bot-originated non-message activities
                             if (activity && activity.from?.role === 'bot' && activity.type !== 'message') {
                                 // Keep all original fields (attachments, channelData, etc.) and set type to 'message'
                                 const normalized = Object.assign({}, activity, { type: 'message' });

                                 // If there's no visible text, try to extract something from channelData or attachments for accessibility
                                 if (!normalized.text) {
                                     normalized.text =
                                         activity.text || 
                                         activity.channelData?.text ||
                                         activity.channelData?.message ||
                                         (activity.attachments && activity.attachments.length ? '[Adaptive Card]' : '');
                                 }

                                 action = Object.assign({}, action, { payload: { activity: normalized } });
                             }

                             const hasChoiceSet = activity.attachments?.some(att => {
                                 const content = att.content;
                                 return content?.type === 'AdaptiveCard' &&
                                     content?.id === 'specialtySelectionAC_id';
                             });
                             const hasGenderPreference = activity.attachments?.some(att => {
                                 const content = att.content;
                                 return content?.type === 'AdaptiveCard' &&
                                     content?.id === 'genderPreferenceAC_id';
                             });
                             const hasAdultCheck = activity.attachments?.some(att => {
                                 const content = att.content;
                                 return content?.type === 'AdaptiveCard' &&
                                     content?.id === 'adultCheckAC_id';
                             });
                             if (hasChoiceSet || hasGenderPreference || hasAdultCheck) {
                                 $(".webchat__send-box-text-box__input").prop("disabled", true);
                             }
                         }
                         if (action.type === 'DIRECT_LINE/POST_ACTIVITY') {
                             // Re-enable input box after user submits
                             $(".webchat__send-box-text-box__input").prop("disabled", false);
                         }
                         return next(action);
                     };
                 };
             });
         }

         function startChat() {
             store = createChatStore();
             var settingsId = encodeURIComponent('58362b8c-2778-480d-aab3-9189ec0acded');
             var tokenUrl = '/_UPMC/HealthBot/GetDirectLineToken?settingsId=' + settingsId;
             fetch(tokenUrl , { method: 'POST' })
                 .then((response) => response.json())
                 .then((data) => {
                     if (data.isSuccess) {
                         const DIRECT_LINE_TOKEN = data.token;
                         CONVERSATION_ID = data.conversationId;
                         DIRECTLINE = window.WebChat.createDirectLine({ token: DIRECT_LINE_TOKEN });
                         window.WebChat.renderWebChat(
                             {
                                 activityMiddleware: activityMiddleware,
                                 directLine: DIRECTLINE,
                                 userID: CONVERSATION_ID,
                                 username: USERNAME,
                                 locale: "en-US",
                                 styleOptions,
                                 store: store,
                                 cardActionMiddleware: cardActionMiddleware(CONVERSATION_ID),
                             },
                             document.getElementById("webchat")
                         );
                         initReferenceDetailsObserver();
                         //trigger Piwik tracking when the chat is initiated
                         window.dataLayer.push({ 'event': 'upmc-aichat-chatInitiated', 'upmc-aichat-chatID': data.conversationId });
                         setTimeout(() => {
                             const inputField = document.querySelector('.webchat__send-box-text-box__input');
                             if (inputField) {
                                 inputField.setAttribute('maxLength', '125');
                                 inputField.setAttribute('placeholder', 'Type your question here');
                             }
                         }, 1000); // Delay to ensure the input field is available
                     }
                     else {
                         //let the user know there is an issue
                         console.error("Error:", "DirectLine authentication failed with status code: " + data.statusCode);
                         document.getElementById("webchat").innerHTML = "
" + 'Sorry, the connection to the AI agent failed. Please attempt to refresh the page. If this does not resolve the issue, try clearing your cookies or temporarily disabling your ad blocker to make use of the tool.' + "";
                         document.getElementById("webchat").classList.add("ErrorMessage");
                     }
                 })
                 .catch(error => {
                     console.error("Error:", "DirectLine authentication failed with error message: " + error.message);
                     document.getElementById("webchat").innerHTML = "
" + 'Sorry, the connection to the AI agent failed. Please attempt to refresh the page. If this does not resolve the issue, try clearing your cookies or temporarily disabling your ad blocker to make use of the tool.' + "";
                     document.getElementById("webchat").classList.add("ErrorMessage");
                 });
             chatState = true;
         }
         function refreshChat() {
             DIRECTLINE.postActivity({
                 from: { id: CONVERSATION_ID, name: USERNAME },
                 type: 'message',
                 text: 'Start over'
             }).subscribe();
         }



         // Combined handler for only the explicit launcher controls (prevents catching buttons inside the rendered webchat/carousel)
         $(document).on('click', '.launch-chat-button button', function (e) {
             e.preventDefault();
             UPMCChatToggle();
             if (!chatState) {
                 startChat();
             }
         });

         $(".UPMCChatClose").click(function () {
             UPMCChatToggle();
         });

         function UPMCChatToggle() {
             if ($(".UPMCChatContainer").css("visibility") === "hidden") {
                 $(".UPMCChatContainer").css({
                     "visibility": "visible",
                     "opacity": "1",
                     "bottom": "35px"
                 });
             } else {
                 $(".UPMCChatContainer").css({
                     "visibility": "hidden",
                     "opacity": "0",
                     "bottom": "-155px"
                 });
             }
         }

         $(".UPMCChatHelpButton").click(function () {
             UPMCChatHelpToggle();
         });

         $(".UPMCChatRestartButton").click(function () {
             // Clear provider card buffer
             providerCardBuffer = [];

             // Clear carousel timer
             if (providerBufferTimer) {
                 clearTimeout(providerBufferTimer);
                 providerBufferTimer = null;
             }

             // End DirectLine connection
             if (DIRECTLINE) {
                 DIRECTLINE.end();
                 DIRECTLINE = null;
             }

             // Disconnect the references observer
             if (referencesObserver) {
                 referencesObserver.disconnect();
                 referencesObserver = null;
             }

             // Completely recreate the webchat DOM element
             const oldWebchatElement = document.getElementById('webchat');
             if (oldWebchatElement) {
                 const newWebchatElement = document.createElement('div');
                 newWebchatElement.id = 'webchat';
                 newWebchatElement.className = 'UPMCChatFrame';
                 newWebchatElement.setAttribute('role', 'main');
                 oldWebchatElement.parentNode.replaceChild(newWebchatElement, oldWebchatElement);
             }

             // Reset all chat state variables
             chatState = false;
             CONVERSATION_ID = null;
             carouselStore = null;

             // Reinitialize the chat from scratch (startChat will recreate the store)
             startChat();
         });

         function UPMCChatHelpToggle() {
             $(".UPMCChatHelpText").slideToggle("1s");
         }

         // Initialize tooltips 
         $('.launch-chat-button button').tooltip({
             container: '.launch-chat-button'
         });
         $('.launch-chat-button button').tooltip('show');

         //$('.UPMCChatRestartButton, .UPMCChatHelpButton, .UPMCChatClose').tooltip({
         //    container: '.UPMCChatContainer'
         //});

         $(".launch-chat-button").css({
             "visibility": "visible",
         });


         $(document).on('click', '.UPMCChatKeyword', function (e) {
             e.preventDefault();
             var keyword = $(this).data('keyword');
             if (typeof store !== "undefined" && keyword) {
                 store.dispatch({
                     type: 'WEB_CHAT/SEND_MESSAGE',
                     payload: {
                         text: keyword
                     }
                 });
             }
         });

     });








